import Foundation

/// Persistent build seed record matching `seed.json` generated by `build_seed.py`.
package struct BuildSeedRecord: Codable, Equatable, Sendable {
    package var schema: Int?
    package var titleID: String
    package var baseTitleID: String?
    package var pkgVer: String?
    package var appName: String?
    package var appVersion: String?
    package var bundleID: String?
    package var lang: String?
    package var langsAvailable: [String]?
    package var gfxAPI: String?
    package var chain: String?
    package var profileID: String?
    package var profileKind: String?
    package var isMultiProgram: Bool?
    package var usesJIT: Bool?
    package var hasAOC: Bool?
    package var hasHTML: Bool?
    package var hasIcon: Bool?
    package var inputsDigest: String?
    package var romfsIdentity: String?
    package var updatedAt: String?

    enum CodingKeys: String, CodingKey {
        case schema
        case titleID = "title_id"
        case baseTitleID = "base_title_id"
        case pkgVer = "pkg_ver"
        case appName = "app_name"
        case appVersion = "app_version"
        case bundleID = "bundle_id"
        case lang
        case langsAvailable = "langs_available"
        case gfxAPI = "gfx_api"
        case chain
        case profileID = "profile_id"
        case profileKind = "profile_kind"
        case isMultiProgram = "is_multi_program"
        case usesJIT = "uses_jit"
        case hasAOC = "has_aoc"
        case hasHTML = "has_html"
        case hasIcon = "has_icon"
        case inputsDigest = "inputs_digest"
        case romfsIdentity = "romfs_identity"
        case updatedAt = "updated_at"
    }

    package init(
        schema: Int? = 1,
        titleID: String,
        baseTitleID: String? = nil,
        pkgVer: String? = nil,
        appName: String? = nil,
        appVersion: String? = nil,
        bundleID: String? = nil,
        lang: String? = nil,
        langsAvailable: [String]? = nil,
        gfxAPI: String? = nil,
        chain: String? = nil,
        profileID: String? = nil,
        profileKind: String? = nil,
        isMultiProgram: Bool? = nil,
        usesJIT: Bool? = nil,
        hasAOC: Bool? = nil,
        hasHTML: Bool? = nil,
        hasIcon: Bool? = nil,
        inputsDigest: String? = nil,
        romfsIdentity: String? = nil,
        updatedAt: String? = nil
    ) {
        self.schema = schema
        self.titleID = titleID
        self.baseTitleID = baseTitleID
        self.pkgVer = pkgVer
        self.appName = appName
        self.appVersion = appVersion
        self.bundleID = bundleID
        self.lang = lang
        self.langsAvailable = langsAvailable
        self.gfxAPI = gfxAPI
        self.chain = chain
        self.profileID = profileID
        self.profileKind = profileKind
        self.isMultiProgram = isMultiProgram
        self.usesJIT = usesJIT
        self.hasAOC = hasAOC
        self.hasHTML = hasHTML
        self.hasIcon = hasIcon
        self.inputsDigest = inputsDigest
        self.romfsIdentity = romfsIdentity
        self.updatedAt = updatedAt
    }
}

/// Metadata describing a RomFS image's embedded DMMSLTR1 shader trailer from `romfs_image.py --inspect-msl`.
package struct RomfsTrailerStatus: Codable, Equatable, Sendable {
    package var hasTrailer: Bool
    package var version: Int?
    package var gfxAPI: String?
    package var flags: Int?
    package var multiProgram: Bool
    package var chain: String?
    package var baseRomfsSize: Int64?
    package var mslOffset: Int64?
    package var mslSize: Int64?
    package var fileSize: Int64?
    package var files: Int?

    enum CodingKeys: String, CodingKey {
        case hasTrailer = "has_trailer"
        case version
        case gfxAPI = "gfx_api"
        case flags
        case multiProgram = "multi_program"
        case chain
        case baseRomfsSize = "base_romfs_size"
        case mslOffset = "msl_offset"
        case mslSize = "msl_size"
        case fileSize = "file_size"
        case files
    }

    package init(
        hasTrailer: Bool = false,
        version: Int? = nil,
        gfxAPI: String? = nil,
        flags: Int? = nil,
        multiProgram: Bool = false,
        chain: String? = nil,
        baseRomfsSize: Int64? = nil,
        mslOffset: Int64? = nil,
        mslSize: Int64? = nil,
        fileSize: Int64? = nil,
        files: Int? = nil
    ) {
        self.hasTrailer = hasTrailer
        self.version = version
        self.gfxAPI = gfxAPI
        self.flags = flags
        self.multiProgram = multiProgram
        self.chain = chain
        self.baseRomfsSize = baseRomfsSize
        self.mslOffset = mslOffset
        self.mslSize = mslSize
        self.fileSize = fileSize
        self.files = files
    }
}

/// Decision for managing RomFS image shader trailer.
package enum TrailerAction: String, Equatable, Sendable {
    case skip
    case append
    case replace
}

/// Build seed cache inspection, candidate resolution, and trailer validation for fast refresh builds.
package enum BuildSeedCache {
    /// The default directory where build seeds are stored.
    package static func defaultRoot(
        home: String = NSHomeDirectory(),
        env: [String: String] = ProcessInfo.processInfo.environment
    ) -> String {
        if let override = env["DM_SEED_CACHE_DIR"], !override.isEmpty {
            return override
        }
        return home + "/Library/Application Support/nxnative/build-seeds"
    }

    /// Normalized seed folder path for a title ID.
    package static func seedDirectory(for titleID: String, seedRoot: String = defaultRoot()) -> String {
        let tid = titleID.trimmingCharacters(in: .whitespacesAndNewlines).uppercased()
        return seedRoot + "/" + tid
    }

    /// The fast refresh execution path depending on shader chain compatibility.
    package enum RefreshPath: String, Equatable, Sendable {
        /// Chain matches: fast refresh (~15s) reusing metal sources.
        case pathA = "pathA"
        /// Chain differs: prefill recompile from cached MSL sources.
        case pathB = "pathB"
    }

    /// Result of inspecting a build seed directory.
    package struct Inspection: Equatable, Sendable {
        package var isValid: Bool
        package var reason: String?
        package var record: BuildSeedRecord?
        package var path: RefreshPath?
        package var seedDir: String

        package var isUsable: Bool { isValid && record != nil }

        package init(
            isValid: Bool,
            reason: String? = nil,
            record: BuildSeedRecord? = nil,
            path: RefreshPath? = nil,
            seedDir: String
        ) {
            self.isValid = isValid
            self.reason = reason
            self.record = record
            self.path = path
            self.seedDir = seedDir
        }
    }

    private static func normalizeChain(_ c: String?) -> String? {
        guard let c, !c.isEmpty else { return nil }
        let trimmed = c.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        return trimmed.hasPrefix("b-") ? String(trimmed.dropFirst(2)) : trimmed
    }

    /// Verifies `seed.json`, `ExeFS/`, `shader/pkg/`, `shader/tables/{c1_full.tsv,cb_extent.tsv}` (if NVN), and `shader/ios/`
    /// compares `chain` with `EngineLayout.shaderChain(repo:)` to distinguish `.pathA` vs `.pathB`.
    package static func inspect(
        titleID: String,
        seedRoot: String = defaultRoot(),
        repoPath: String = "",
        fm: FileManager = .default
    ) -> Inspection {
        let tid = titleID.trimmingCharacters(in: .whitespacesAndNewlines).uppercased()
        guard !tid.isEmpty else {
            return Inspection(isValid: false, reason: "empty title id", seedDir: seedRoot)
        }
        let seedDir = seedDirectory(for: tid, seedRoot: seedRoot)
        var isDir: ObjCBool = false
        guard fm.fileExists(atPath: seedDir, isDirectory: &isDir), isDir.boolValue else {
            return Inspection(isValid: false, reason: "seed directory missing", seedDir: seedDir)
        }

        let seedJSONPath = seedDir + "/seed.json"
        guard let data = fm.contents(atPath: seedJSONPath),
              let record = try? JSONDecoder().decode(BuildSeedRecord.self, from: data) else {
            return Inspection(isValid: false, reason: "corrupt or missing seed.json", seedDir: seedDir)
        }

        guard record.titleID.uppercased() == tid else {
            return Inspection(isValid: false, reason: "seed title id mismatch", record: record, seedDir: seedDir)
        }

        let exefsDir = seedDir + "/ExeFS"
        guard fm.fileExists(atPath: exefsDir, isDirectory: &isDir), isDir.boolValue,
              let exefsEntries = try? fm.contentsOfDirectory(atPath: exefsDir),
              exefsEntries.contains(where: { !$0.hasPrefix(".") }) else {
            return Inspection(isValid: false, reason: "missing or empty ExeFS directory", record: record, seedDir: seedDir)
        }

        let shaderPkg = seedDir + "/shader/pkg"
        guard fm.fileExists(atPath: shaderPkg, isDirectory: &isDir), isDir.boolValue else {
            return Inspection(isValid: false, reason: "missing shader/pkg directory", record: record, seedDir: seedDir)
        }

        let isNVN = record.gfxAPI == nil || record.gfxAPI?.lowercased() == "nvn"
        if isNVN {
            let tablesDir = seedDir + "/shader/tables"
            let c1 = tablesDir + "/c1_full.tsv"
            let cb = tablesDir + "/cb_extent.tsv"
            guard fm.fileExists(atPath: c1), fm.fileExists(atPath: cb) else {
                return Inspection(isValid: false, reason: "missing shader/tables {c1_full.tsv, cb_extent.tsv}", record: record, seedDir: seedDir)
            }
        }

        let shaderIOS = seedDir + "/shader/ios"
        guard fm.fileExists(atPath: shaderIOS, isDirectory: &isDir), isDir.boolValue else {
            return Inspection(isValid: false, reason: "missing shader/ios directory", record: record, seedDir: seedDir)
        }

        let repoChain = EngineLayout.shaderChain(repo: repoPath)
        let normSeedChain = normalizeChain(record.chain)
        let normRepoChain = normalizeChain(repoChain)

        let refreshPath: RefreshPath
        if !isNVN {
            refreshPath = .pathA
        } else if let normSeedChain, let normRepoChain, normSeedChain == normRepoChain {
            refreshPath = .pathA
        } else {
            refreshPath = .pathB
        }

        return Inspection(isValid: true, reason: nil, record: record, path: refreshPath, seedDir: seedDir)
    }

    /// Finds existing Mac `.app`, `<outDir>/games/<GameName>/<GameName>.img`, legacy `<outDir>/games/<TID>/romfs.img` for `--prefill-msl`.
    package static func prefillCandidates(
        titleID: String,
        outDir: String,
        gameName: String? = nil,
        macAppPath: String? = nil,
        workDir: String? = nil,
        fm: FileManager = .default
    ) -> [String] {
        let tid = titleID.trimmingCharacters(in: .whitespacesAndNewlines).uppercased()
        var candidates: [String] = []
        var seen = Set<String>()

        func addCandidate(_ path: String) {
            guard !path.isEmpty, !seen.contains(path), fm.fileExists(atPath: path) else { return }
            seen.insert(path)
            candidates.append(path)
        }

        if let macAppPath, !macAppPath.isEmpty {
            addCandidate(macAppPath)
        }

        if !outDir.isEmpty {
            let gamesRoot = outDir + "/games"
            if let gameName, !gameName.isEmpty {
                let sanitized = RomFSArchive.sanitizeGameName(gameName, fallback: tid)
                addCandidate(gamesRoot + "/" + sanitized + "/" + sanitized + ".img")
                addCandidate(gamesRoot + "/" + gameName + "/" + gameName + ".img")
                addCandidate(outDir + "/" + gameName + ".app")
                addCandidate(outDir + "/" + sanitized + ".app")
            }
            addCandidate(gamesRoot + "/" + tid + "/" + tid + ".img")
            addCandidate(gamesRoot + "/" + tid + "/romfs.img")
            addCandidate(gamesRoot + "/" + tid.lowercased() + "/romfs.img")

            for dir in RomFSArchive.archiveDirectories(forTitleID: tid, gamesRoot: gamesRoot, fm: fm) {
                if let primary = RomFSArchive.primaryImagePath(in: dir, fm: fm) {
                    addCandidate(primary)
                }
            }

            if let entries = try? fm.contentsOfDirectory(atPath: outDir) {
                for entry in entries where entry.hasSuffix(".app") {
                    addCandidate(outDir + "/" + entry)
                }
            }
        }

        if let workDir, !workDir.isEmpty {
            addCandidate(workDir + "/shader/ios")
            addCandidate(workDir + "/extract")
            addCandidate(workDir + "/shader/cache")
        }

        return candidates
    }

    /// Parses JSON output from `romfs_image.py --inspect-msl`.
    package static func parseTrailerStatus(from jsonString: String) -> RomfsTrailerStatus? {
        guard let data = jsonString.data(using: .utf8) else { return nil }
        return try? JSONDecoder().decode(RomfsTrailerStatus.self, from: data)
    }

    /// Parses JSON data output from `romfs_image.py --inspect-msl`.
    package static func parseTrailerStatus(from data: Data) -> RomfsTrailerStatus? {
        try? JSONDecoder().decode(RomfsTrailerStatus.self, from: data)
    }

    /// Evaluates whether an existing RomFS image trailer already matches the target shader source, enabling 0-I/O skip.
    package static func shouldSkipTrailerInjection(
        status: RomfsTrailerStatus,
        gfxAPI: String?,
        chain: String?,
        multiProgram: Bool
    ) -> Bool {
        guard status.hasTrailer else { return false }
        guard status.multiProgram == multiProgram else { return false }

        let targetAPI = (gfxAPI?.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()).flatMap { $0.isEmpty ? nil : $0 } ?? "nvn"
        let statusAPI = (status.gfxAPI?.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()).flatMap { $0.isEmpty ? nil : $0 } ?? "nvn"
        guard targetAPI == statusAPI else { return false }

        if targetAPI == "nvn" {
            let normStatusChain = normalizeChain(status.chain)
            let normTargetChain = normalizeChain(chain)
            guard let normStatusChain, let normTargetChain, normStatusChain == normTargetChain else { return false }
        }

        return true
    }

    /// Evaluates whether an existing RomFS image trailer in JSON form matches the target shader source.
    package static func shouldSkipTrailerInjection(
        inspectJSON: String,
        gfxAPI: String?,
        chain: String?,
        multiProgram: Bool
    ) -> Bool {
        guard let status = parseTrailerStatus(from: inspectJSON) else { return false }
        return shouldSkipTrailerInjection(status: status, gfxAPI: gfxAPI, chain: chain, multiProgram: multiProgram)
    }

    /// Decides whether to skip trailer injection (0 disk I/O), append a new trailer, or replace an existing mismatched trailer.
    package static func trailerAction(
        status: RomfsTrailerStatus,
        gfxAPI: String?,
        chain: String?,
        multiProgram: Bool
    ) -> TrailerAction {
        if !status.hasTrailer {
            return .append
        }
        if shouldSkipTrailerInjection(status: status, gfxAPI: gfxAPI, chain: chain, multiProgram: multiProgram) {
            return .skip
        }
        return .replace
    }
}
